function pickMockPool(pool,n,conceptCounts,conceptCap,cognitiveCounts,cognitiveTarget,difficulty){
  const pref=mockCognitivePreference(difficulty);
  const chosen=[];
  const used=new Set();

  const ranked=(respectCap)=>{
    const candidates=pool.filter(q=>{
      if(used.has(q.id))return false;
      const key=`${q.cat}::${q.concept}`;
      return !respectCap||(conceptCounts[key]||0)<conceptCap;
    });
    return candidates.sort((a,b)=>{
      const ar=(cognitiveCounts[a.cognitiveLevel]||0)<(cognitiveTarget[a.cognitiveLevel]||0);
      const br=(cognitiveCounts[b.cognitiveLevel]||0)<(cognitiveTarget[b.cognitiveLevel]||0);
      if(ar!==br)return ar?-1:1;
      const ap=pref.indexOf(a.cognitiveLevel),bp=pref.indexOf(b.cognitiveLevel);
      if(ap!==bp)return ap-bp;
      return mockCandidateSort(a,b);
    });
  };

  const take=q=>{
    chosen.push(q);used.add(q.id);
    const key=`${q.cat}::${q.concept}`;
    conceptCounts[key]=(conceptCounts[key]||0)+1;
    cognitiveCounts[q.cognitiveLevel]=(cognitiveCounts[q.cognitiveLevel]||0)+1;
  };

  while(chosen.length<n){
    let candidates=ranked(true);
    if(!candidates.length)candidates=ranked(false);
    if(!candidates.length)break;
    take(candidates[0]);
  }
  return chosen;
}

sources.buildMockQuestions:
function buildMockQuestions(modeOrCount){
  const mode=typeof modeOrCount==='string'?modeOrCount:(modeOrCount===60?'full':'half');
  const bp=MOCK_BLUEPRINTS[mode]||MOCK_BLUEPRINTS.full;
  const quotas=mockCategoryQuotas(bp.count);
  const difficultyByCat=allocateMockDifficultyByCategory(quotas,bp);
  const conceptCounts={};
  const cognitiveCounts={'想起':0,'適用':0,'判断':0};
  const cognitiveTarget=bp.cognitive||{'想起':0,'適用':bp.count,'判断':0};
  const out=[];

  MOCK_CATEGORIES.forEach(cat=>{
    const cap=mode==='half'?1:2;
    MOCK_DIFFICULTY_LEVELS.forEach(level=>{
      const n=difficultyByCat[cat][level]||0;
      const pool=QUESTION_BANK.filter(q=>q.cat===cat&&q.difficulty===level);
      out.push(...pickMockPool(pool,n,conceptCounts,cap,cognitiveCounts,cognitiveTarget,level));
    });
  });

  const unique=[];
  const seenIds=new Set();
  for(const q of out){
    if(!seenIds.has(q.id)){unique.push(q);seenIds.add(q.id);}
  }
  if(unique.length<bp.count){
    unique.push(...QUESTION_BANK.filter(q=>!seenIds.has(q.id)).sort(mockCandidateSort).slice(0,bp.count-unique.length));
  }

  const picked=shuffled(unique.slice(0,bp.count));
  const counts={
    categories:Object.fromEntries(MOCK_CATEGORIES.map(c=>[c,picked.filter(q=>q.cat===c).length])),
    difficulty:Object.fromEntries(MOCK_DIFFICULTY_LEVELS.map(level=>[level,picked.filter(q=>q.difficulty===level).length])),
    cognitive:Object.fromEntries(MOCK_COGNITIVE_LEVELS.map(level=>[level,picked.filter(q=>q.cognitiveLevel===level).length])),
    unseen:picked.filter(q=>mockSeen(q)===0).length
  };
  mockCurrentBlueprint={mode,count:bp.count,quotas,difficultyByCat,counts};
  return picked.map(randomizeMockQuestion);
}

sources.mockCandidateSort:
function mockCandidateSort(a,b){
  const sa=mockSeen(a),sb=mockSeen(b);
  if(sa!==sb)return sa-sb;
  const la=mockLastSeen(a),lb=mockLastSeen(b);
  if(la!==lb)return la.localeCompare(lb);
  return Math.random()-.5;
}

sources.allocateMockDifficultyByCategory:
function allocateMockDifficultyByCategory(quotas,bp){
  const result=Object.fromEntries(MOCK_CATEGORIES.map(c=>[c,{'基礎':0,'標準':0,'実戦':0}]));

  const assign=(level,total)=>{
    for(let k=0;k<total;k++){
      const candidates=MOCK_CATEGORIES.filter(cat=>{
        const assigned=Object.values(result[cat]).reduce((a,b)=>a+b,0);
        const available=QUESTION_BANK.filter(q=>q.cat===cat&&q.difficulty===level).length;
        return assigned<quotas[cat] && result[cat][level]<available;
      }).sort((a,b)=>{
        const ra=result[a][level]/Math.max(1,quotas[a]);
        const rb=result[b][level]/Math.max(1,quotas[b]);
        return ra-rb || MOCK_CATEGORIES.indexOf(a)-MOCK_CATEGORIES.indexOf(b);
      });
      if(!candidates.length)break;
      result[candidates[0]][level]++;
    }
  };

  // Reserve practical and basic questions first; fill the remainder with standard.
  assign('実戦',bp.practical);
  assign('基礎',bp.basic);

  MOCK_CATEGORIES.forEach(cat=>{
    const assigned=result[cat]['実戦']+result[cat]['基礎'];
    result[cat]['標準']=Math.max(0,quotas[cat]-assigned);
  });

  // If a category lacks standard questions, replace the shortage with another available tier.
  MOCK_CATEGORIES.forEach(cat=>{
    const stdAvailable=QUESTION_BANK.filter(q=>q.cat===cat&&q.difficulty==='標準').length;
    if(result[cat]['標準']<=stdAvailable)return;
    let shortage=result[cat]['標準']-stdAvailable;
    result[cat]['標準']=stdAvailable;
    for(const level of ['実戦','基礎']){
      const available=QUESTION_BANK.filter(q=>q.cat===cat&&q.difficulty===level).length;
      const room=Math.max(0,available-result[cat][level]);
      const add=Math.min(room,shortage);
      result[cat][level]+=add;shortage-=add;
      if(shortage<=0)break;
    }
  });

  return result;
}

sources.mockCategoryQuotas:
function mockCategoryQuotas(count){
  const base=Math.floor(count/MOCK_CATEGORIES.length);
  const rem=count%MOCK_CATEGORIES.length;
  const start=(profile.mockHistory?.length||0)%MOCK_CATEGORIES.length;
  const q=Object.fromEntries(MOCK_CATEGORIES.map(c=>[c,base]));
  for(let i=0;i<rem;i++) q[MOCK_CATEGORIES[(start+i)%MOCK_CATEGORIES.length]]++;
  return q;
}
